'use strict';

// MODULES //

var exp = require( '@stdlib/math/base/special/exp' );
var pow = require( '@stdlib/math/base/special/pow' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var PI = require( '@stdlib/constants/float64/pi' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Evaluates the probability density function (PDF) for a half-normal distribution with scale parameter `sigma` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} evaluated probability density function
*
* @example
* var y = pdf( 2.0, 1.0 );
* // returns 0.10798193302637613
*
* @example
* var y = pdf( -1.0, 2.0 );
* // returns 0.0
*
* @example
* var y = pdf( 0.0, 1.0 );
* // returns 0.7978845608028654
*
* @example
* var y = pdf( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = pdf( 0.0, NaN );
* // returns NaN
*
* @example
* // Negative scale parameter:
* var y = pdf( 2.0, -1.0 );
* // returns NaN
*
* @example
* var y = pdf( 2.0, 0.0 );
* // returns 0.0
*
* @example
* var y = pdf( 0.0, 0.0 );
* // returns Infinity
*/
function pdf( x, sigma ) {
	var s2;
	var A;
	if (
		isnan( x ) ||
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return NaN;
	}
	if ( x < 0.0 ) {
		return 0.0;
	}
	if ( sigma === 0.0 ) {
		return ( x === 0.0 ) ? PINF : 0.0;
	}
	s2 = pow( sigma, 2.0 );
	A = SQRT2 / ( sigma * sqrt( PI ) );
	return A * exp( -pow( x, 2.0 ) / ( 2.0 * s2 ) );
}


// EXPORTS //

module.exports = pdf;
